(window.webpackJsonpGUI=window.webpackJsonpGUI||[]).push([[190],{1529:function(t,n,e){"use strict";e.r(n),n.default={code:"M3-00",title:"二分搜尋入門暖身",tier:"t3",unlockCode:"M3-00-BinarySearchWarmup",tasks:[{id:"M3-00-01",code:"M3-00-M3-00-01",title:"神祕數字找找看",description:"老師心中把候選數字由小到大排好，請你判斷某個目標數字在不在清單裡。\n\n第一行輸入N，代表清單有N個數字\n\n第二行輸入N個數字（已經由小到大排序），數字間以空白間隔\n\n第三行輸入要查詢的目標數字\n\n如果目標數字有在清單裡，輸出「找到了」；否則輸出「沒找到」。",examples:[{input:"5\n2 4 6 8 10\n6",output:"找到了",explanation:"清單中有6，所以輸出找到了"},{input:"5\n2 4 6 8 10\n7",output:"沒找到",explanation:"清單中沒有7，所以輸出沒找到"}],testCases:[{input:"5\n2 4 6 8 10\n6",expectedOutput:"找到了",score:20},{input:"5\n2 4 6 8 10\n7",expectedOutput:"沒找到",score:20},{input:"1\n42\n42",expectedOutput:"找到了",score:20},{input:"6\n1 3 5 7 9 11\n1",expectedOutput:"找到了",score:20},{input:"6\n1 3 5 7 9 11\n11",expectedOutput:"找到了",score:20}],difficulty:"L2",difficultyLabel:"L2｜進階",sb3Path:"m0/M3-00-BinarySearchWarmup/M3-00-01.sb3"},{id:"M3-00-02",code:"M3-00-M3-00-02",title:"神祕數字在第幾個",description:"承接上一題，這次清單中的數字一樣由小到大排好。請你找出目標數字在清單中的位置（從第1個算起）。\n\n第一行輸入N\n\n第二行輸入N個已排序的數字\n\n第三行輸入要查詢的目標數字\n\n如果找到，輸出目標數字的位置（從1開始算）；如果清單裡沒有這個數字，輸出0。",examples:[{input:"5\n2 4 6 8 10\n6",output:"3",explanation:"6是清單中第3個數字，所以輸出3"},{input:"5\n2 4 6 8 10\n7",output:"0",explanation:"清單中沒有7，所以輸出0"}],testCases:[{input:"5\n2 4 6 8 10\n6",expectedOutput:"3",score:20},{input:"5\n2 4 6 8 10\n7",expectedOutput:"0",score:20},{input:"1\n42\n42",expectedOutput:"1",score:20},{input:"6\n1 3 5 7 9 11\n1",expectedOutput:"1",score:20},{input:"6\n1 3 5 7 9 11\n11",expectedOutput:"6",score:20}],difficulty:"L2",difficultyLabel:"L2｜進階",sb3Path:"m0/M3-00-BinarySearchWarmup/M3-00-02.sb3"},{id:"M3-00-03",code:"M3-00-M3-00-03",title:"猜數字裁判",description:"模擬猜數字遊戲的裁判：給一個正確答案secret，跟一串依序猜測的數字。請你算出玩家是第幾次才猜中（保證猜測序列裡一定會猜中一次）。\n\n第一行輸入secret\n\n第二行輸入M，代表猜測次數\n\n第三行輸入M個猜測值，依序排列，空白分隔\n\n輸出玩家第幾次猜中（從第1次算起）。",examples:[{input:"42\n5\n50 25 40 42 45",output:"4",explanation:"第4次猜到42，答對"},{input:"7\n3\n7 1 9",output:"1",explanation:"第1次就猜中7"}],testCases:[{input:"42\n5\n50 25 40 42 45",expectedOutput:"4",score:20},{input:"7\n3\n7 1 9",expectedOutput:"1",score:20},{input:"100\n4\n50 75 90 100",expectedOutput:"4",score:20},{input:"3\n6\n10 5 2 3 1 8",expectedOutput:"4",score:20},{input:"1\n1\n1",expectedOutput:"1",score:20}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M3-00-BinarySearchWarmup/M3-00-03.sb3"},{id:"M3-00-04",code:"M3-00-M3-00-04",title:"新書該插第幾格",description:"書架上的書已經依照編號由小到大排好。請你決定新書該插入第幾個位置（從第1個算起），插入後書架仍維持由小到大排序。如果新書編號跟書架上已有的編號重複，新書要插在第一個相同編號的前面。\n\n第一行輸入N，代表書架現有N本書\n\n第二行輸入N個已排序的書本編號\n\n第三行輸入新書編號\n\n輸出新書應該插入的位置。",examples:[{input:"5\n10 20 30 40 50\n25",output:"3",explanation:"25要插在30之前，變成第3個"},{input:"5\n10 20 30 40 50\n5",output:"1",explanation:"5比全部都小，插在第1個"}],testCases:[{input:"5\n10 20 30 40 50\n25",expectedOutput:"3",score:17},{input:"5\n10 20 30 40 50\n5",expectedOutput:"1",score:17},{input:"5\n10 20 30 40 50\n60",expectedOutput:"6",score:17},{input:"5\n10 20 30 40 50\n30",expectedOutput:"3",score:17},{input:"1\n100\n100",expectedOutput:"1",score:16},{input:"6\n1 3 3 3 7 9\n3",expectedOutput:"2",score:16}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M3-00-BinarySearchWarmup/M3-00-04.sb3"},{id:"M3-00-05",code:"M3-00-M3-00-05",title:"訂單一次查",description:"已排序的會員編號清單，請你一次查詢多筆會員編號是否存在。\n第一行輸入N，代表會員總數\n第二行輸入N個已排序的會員編號\n第三行輸入Q，代表要查詢的筆數\n第四行輸入Q個要查詢的編號，空白分隔\n依查詢順序，依序輸出每筆查詢的結果「有」或「無」，用空白分隔成一行。",examples:[{input:"5\n3 8 15 22 30\n3\n8 10 22",output:"有 無 有",explanation:"8有、10沒有、22有"},{input:"5\n3 8 15 22 30\n2\n3 30",output:"有 有",explanation:"3跟30都有"}],testCases:[{input:"5\n3 8 15 22 30\n3\n8 10 22",expectedOutput:"有 無 有",score:25},{input:"5\n3 8 15 22 30\n2\n3 30",expectedOutput:"有 有",score:25},{input:"1\n100\n2\n100 99",expectedOutput:"有 無",score:25},{input:"6\n2 4 6 8 10 12\n4\n1 4 13 12",expectedOutput:"無 有 無 有",score:25}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M3-00-BinarySearchWarmup/M3-00-05.sb3"},{id:"M3-00-06",code:"M3-00-M3-00-06",title:"打折門檻落點",description:"店家依消費金額設定折扣門檻（門檻清單由小到大排序），請你判斷某筆消費金額達到第幾個門檻（即金額大於等於的最大門檻編號）。如果金額沒有達到任何門檻，輸出0。\n\n第一行輸入N，代表門檻數量\n\n第二行輸入N個已排序的門檻金額\n\n第三行輸入這筆消費金額\n\n輸出達到的門檻編號。",examples:[{input:"3\n500 1000 2000\n1500",output:"2",explanation:"1500達到1000的門檻，但沒到2000，所以是第2個門檻"},{input:"3\n500 1000 2000\n300",output:"0",explanation:"300沒達到任何門檻，輸出0"}],testCases:[{input:"3\n500 1000 2000\n1500",expectedOutput:"2",score:17},{input:"3\n500 1000 2000\n300",expectedOutput:"0",score:17},{input:"3\n500 1000 2000\n2000",expectedOutput:"3",score:17},{input:"4\n100 200 300 400\n250",expectedOutput:"2",score:17},{input:"1\n999\n999",expectedOutput:"1",score:16},{input:"4\n100 200 300 400\n99",expectedOutput:"0",score:16}],difficulty:"L3",difficultyLabel:"L3｜挑戰",sb3Path:"m0/M3-00-BinarySearchWarmup/M3-00-06.sb3"}]}}}]);